typedef struct {
    char *s;
} Str;

static char *dupstr(const char *s) {
    size_t n = strlen(s);
    char *p = (char *)malloc(n + 1);
    if (!p) exit(1);
    memcpy(p, s, n + 1);
    return p;
}

static void push(Str **arr, int *sz, int *cap, char *s) {
    if (*sz >= *cap) {
        *cap = (*cap == 0 ? 16 : (*cap * 2));
        *arr = (Str *)realloc(*arr, (*cap) * sizeof(Str));
        if (!*arr) exit(1);
    }
    (*arr)[*sz].s = s;
    (*sz)++;
}

int main(void) {
    int r, c, w, s;
    int first_dataset = 1;

    while (scanf("%d %d %d %d", &r, &c, &w, &s) == 4) {
        int ch = getchar(); /* consume endline after the 4 integers */
        (void)ch;

        Str *items = NULL;
        int n = 0, cap = 0;

        char line[MAXLINE];

        /* Read dataset lines until a line containing exactly "#" */
        while (fgets(line, sizeof(line), stdin)) {
            size_t len = strlen(line);
            while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r')) {
                line[--len] = '\0';
            }

            if (strcmp(line, "#") == 0) break;

            if ((int)len == 0) {
                push(&items, &n, &cap, dupstr(""));
            } else {
                int pos = 0;
                while (pos < (int)len) {
                    int take = w;
                    if (pos + take > (int)len) take = (int)len - pos;
                    char *part = (char *)malloc(take + 1);
                    if (!part) exit(1);
                    memcpy(part, line + pos, take);
                    part[take] = '\0';
                    push(&items, &n, &cap, part);
                    pos += take;
                }
            }
        }

        if (!first_dataset) {
            printf("\n");
        }
        first_dataset = 0;

        int per_page = r * c;
        int pages = (n + per_page - 1) / per_page;
        if (pages == 0) pages = 1;

        for (int p = 0; p < pages; p++) {
            int base = p * per_page;

            for (int row = 0; row < r; row++) {
                for (int col = 0; col < c; col++) {
                    int idx = base + col * r + row;

                    if (idx < n) {
                        int len = (int)strlen(items[idx].s);
                        fputs(items[idx].s, stdout);
                        for (int k = len; k < w; k++) putchar('.');
                    } else {
                        for (int k = 0; k < w; k++) putchar('.');
                    }

                    if (col != c - 1) {
                        for (int k = 0; k < s; k++) putchar('.');
                    }
                }
                putchar('\n');
            }

            printf("*\n");
        }

        for (int i = 0; i < n; i++) free(items[i].s);
        free(items);
    }

    return 0;
}

