            // Remove carriage return if present
            if (!text_line.empty() && text_line.back() == '\r') {
                text_line.pop_back();
            }
            text_lines.push_back(text_line);
        }

        // Process and format the dataset
        dataset_num++;
        cout << "Data Set " << dataset_num << ":" << endl;

        // Calculate number of pages
        int total_lines = text_lines.size();
        int lines_per_page = lines_per_col * cols_per_page;
        int num_pages = (total_lines + lines_per_page - 1) / lines_per_page;
        if (num_pages == 0) num_pages = 1;

        for (int page = 0; page < num_pages; page++) {
            if (page > 0) {
                cout << "=====" << endl;
            }

            int start_line = page * lines_per_page;

            // Process each group of lines_per_col lines (each row group)
            for (int row_group = 0; row_group < lines_per_col; row_group++) {
                // For each column in this row group
                for (int col = 0; col < cols_per_page; col++) {
                    int line_index = start_line + col * lines_per_col + row_group;

                    if (line_index < total_lines) {
                        string current_line = text_lines[line_index];
                        // Wrap long lines
                        if ((int)current_line.length() > col_width) {
                            current_line = current_line.substr(0, col_width);
                        }
                        // Pad with dots if too short
