public class TextColumnFormatter {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder output = new StringBuilder();
        boolean firstDataSet = true;

        while (true) {
            String line = br.readLine();
            if (line == null) break;

            String[] params = line.trim().split("\\s+");
            if (params.length < 4) continue;

            int linesPerCol = Integer.parseInt(params[0]);
            int colsPerPage = Integer.parseInt(params[1]);
            int colWidth = Integer.parseInt(params[2]);
            int spacing = Integer.parseInt(params[3]);

            // Read text lines until we encounter a line with "***"
            List<String> textLines = new ArrayList<>();
            while (true) {
                String textLine = br.readLine();
                if (textLine == null) break;
                if (textLine.trim().equals("***")) break;
                textLines.add(textLine);
            }

            // Process text lines: wrap long lines and fill with dots
            List<String> processedLines = new ArrayList<>();
            for (String text : textLines) {
                // Wrap text to fit column width
                int start = 0;
                while (start < text.length()) {
                    int end = Math.min(start + colWidth, text.length());
                    String segment = text.substring(start, end);
                    // Pad with dots if needed
                    if (segment.length() < colWidth) {
                        StringBuilder sb = new StringBuilder(segment);
                        while (sb.length() < colWidth) {
                            sb.append('.');
                        }
                        segment = sb.toString();
                    }
                    processedLines.add(segment);
                    start = end;
                }
            }

            // Fill remaining spots with dots
            int totalCells = linesPerCol * colsPerPage;
            while (processedLines.size() < totalCells) {
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < colWidth; i++) {
                    sb.append('.');
                }
                processedLines.add(sb.toString());
            }

            // Build output
            if (!firstDataSet) {
                output.append("----------\n");
            }
            firstDataSet = false;

            // Print columns
            for (int row = 0; row < linesPerCol; row++) {
                for (int col = 0; col < colsPerPage; col++) {
                    int index = col * linesPerCol + row;
                    if (index < processedLines.size()) {
                        output.append(processedLines.get(index));
                        if (col < colsPerPage - 1) {
                            for (int s = 0; s < spacing; s++) {
                                output.append(' ');
                            }
                        }
                    }
                }
                output.append('\n');
            }

            // Page delimiter
            output.append("====\n");

            // Check for end of data set
            if (br.readLine() == null) break;
        }

        System.out.print(output.toString());
    }
}

