public class Main {
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        Integer nextInt() throws IOException {
            String s = next();
            if (s == null) return null;
            return Integer.parseInt(s);
        }

        String nextLine() throws IOException {
            st = null;
            return br.readLine();
        }
    }

    static String padRight(String s, int width) {
        if (s.length() >= width) return s;
        StringBuilder sb = new StringBuilder(width);
        sb.append(s);
        while (sb.length() < width) sb.append('.');
        return sb.toString();
    }

    static List<String> wrapLine(String line, int width) {
        List<String> parts = new ArrayList<>();
        if (line.length() == 0) {
            parts.add("");
            return parts;
        }
        for (int i = 0; i < line.length(); i += width) {
            parts.add(line.substring(i, Math.min(i + width, line.length())));
        }
        return parts;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();
        boolean firstDataset = true;

        while (true) {
            Integer rObj = fs.nextInt();
            if (rObj == null) break;
            int rows = rObj;
            int cols = fs.nextInt();
            int width = fs.nextInt();
            int space = fs.nextInt();

            if (rows == 0 && cols == 0 && width == 0 && space == 0) break;

            List<String> logicalLines = new ArrayList<>();
            while (true) {
                String line = fs.nextLine();
                if (line == null) break;
                if (line.equals("#")) break;
                logicalLines.add(line);
            }

            List<String> pieces = new ArrayList<>();
            for (String line : logicalLines) {
                pieces.addAll(wrapLine(line, width));
            }

            String gap = ".".repeat(space);

            int idx = 0;
            while (idx < pieces.size()) {
                for (int r = 0; r < rows; r++) {
                    StringBuilder rowOut = new StringBuilder();
                    for (int c = 0; c < cols; c++) {
                        int pos = idx + c * rows + r;
                        String cell = (pos < pieces.size()) ? pieces.get(pos) : "";
                        rowOut.append(padRight(cell, width));
                        if (c + 1 < cols) rowOut.append(gap);
                    }
                    out.append(rowOut).append('\n');
                }
                idx += rows * cols;
                out.append('\n');
            }

            out.append("#\n");
            firstDataset = false;
        }

        System.out.print(out.toString());
    }
}

import sys

def solve():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return

    out = []
    i = 0
    first_dataset = True

    while i < len(lines):
        # Skip accidental empty lines between datasets
        while i < len(lines) and lines[i].strip() == "":
            i += 1
        if i >= len(lines):
            break

        parts = lines[i].split()
        if len(parts) < 4:
            break

        r, c, w, s = map(int, parts[:4])
        i += 1

        # End marker
        if r == 0 and c == 0 and w == 0 and s == 0:
            break

        # Collect text lines until next parameter line or EOF.
        # Dataset text is terminated by a line exactly containing "#".
        text_lines = []
        while i < len(lines):
            if lines[i] == "#":
                i += 1
                break
            text_lines.append(lines[i])
            i += 1

        # Wrap each input line into chunks of width w.
        pieces = []
        for line in text_lines:
            if line == "":
                pieces.append("")
            else:
                for j in range(0, len(line), w):
                    pieces.append(line[j:j + w])

        page_size = r * c
        gap = " " * s

        idx = 0
        while idx < len(pieces) or idx == 0:
            # Print one page
            for row in range(r):
                cols = []
                for col in range(c):
                    k = idx + col * r + row
                    if k < len(pieces):
                        seg = pieces[k]
                    else:
                        seg = ""
                    cols.append(seg.ljust(w, '.'))
                out.append(gap.join(cols))
            out.append("")  # page delimiter (blank line)

            idx += page_size
            if idx >= len(pieces):
                break

        out.append("#")  # dataset delimiter

    sys.stdout.write("\n".join(out))

